public class MinHeap {
    private int[] heap;
    private int size;
    private int capacity;

    public MinHeap(int capacity) {
        this.capacity = capacity;
        heap = new int[capacity];
        size = 0;
    }

    public void insert(int val) {
        if (size == capacity) {
            throw new IllegalStateException("Heap is full");
        }
        heap[size] = val;
        siftUp(size);
        size++;
    }

    public int extractMin() {
        if (size == 0) {
            throw new IllegalStateException("Heap is empty");
        }
        int min = heap[0];
        heap[0] = heap[size - 1];
        size--;
        siftDown(0);
        return min;
    }

    private void siftUp(int i) {
        int current = heap[i];
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (heap[parent] <= current) break;
            heap[i] = heap[parent];
            i = parent;
        }
        heap[i] = current;
    }

    private void siftDown(int i) {
        int current = heap[i];
        int half = size / 2;
        while (i < half) {
            int left = 2 * i + 1;
            int right = left + 1;
            int smallest = left;
            if (right < size && heap[right] < heap[left]) {
                smallest = right;
            }
            if (heap[smallest] >= current) break;
            heap[i] = heap[smallest];
            i = smallest;
        }
        heap[i] = current;
    }
}

