import java.util.Stack;

public class QueueUsingTwoStacks<T> {
    private Stack<T> stackNewest = new Stack<>();
    private Stack<T> stackOldest = new Stack<>();

    public void enqueue(T item) {
        stackNewest.push(item);
    }

    public T dequeue() {
        shiftStacks();
        if (stackOldest.isEmpty()) throw new RuntimeException("Queue is empty");
        return stackOldest.pop();
    }

    public T peek() {
        shiftStacks();
        if (stackOldest.isEmpty()) throw new RuntimeException("Queue is empty");
        return stackOldest.peek();
    }

    public boolean isEmpty() {
        return stackNewest.isEmpty() && stackOldest.isEmpty();
    }

    private void shiftStacks() {
        if (stackOldest.isEmpty()) {
            while (!stackNewest.isEmpty()) {
                stackOldest.push(stackNewest.pop());
            }
        }
    }
}

